with accepted as (insert into public.catalog_spells (id, number, slug, name, universe_id, status, payload) values ('Spell_2_Fus-Ro-Dah_2026-10-06_719dd0e2-506a-4e67-9b02-04d4af1b4932', 2, 'fus-ro-dah', 'Fus Ro Dah', 'skyrim', 'published', '{"id":"Spell_2_Fus-Ro-Dah_2026-10-06_719dd0e2-506a-4e67-9b02-04d4af1b4932","number":2,"name":"Fus Ro Dah","worldId":"skyrim","sourceTitle":"The Elder Scrolls V: Skyrim","medium":"Games","kind":"Unrelenting Force","language":"Dragon language","pronunciation":"FOOS · ROH · DAH","pronunciationNote":"An approximate English reader aid. Bethesda identifies each word as a single syllable; the in-game voice is the performance reference.","syllables":["FUS","RO","DAH"],"definition":"A Dragon Shout that pushes opponents away with powerful force.","usage":"Its full three-word form can send opponents airborne. Strength and effects depend on the game context.","etymology":"Bethesda describes the Dragon language as drawing on several Germanic languages, especially Old English. This is language inspiration; an individual word-origin analysis is not confirmed here.","etymologyStatus":"Unconfirmed","breakdown":[{"label":"Fus","meaning":"The first word of the three-word shout."},{"label":"Ro","meaning":"The second word of the three-word shout."},{"label":"Dah","meaning":"The final word of the three-word shout."}],"danger":4,"utility":4,"skill":"Advanced","category":"Force","accent":"wind","aliases":["Unrelenting Force","Thu’um","Dragon Shout"],"entryType":"ability","casters":["The Dragonborn"],"evidenceStatus":"verified","pronunciationStatus":"approximate","continuity":"The Elder Scrolls V: Skyrim","effect":"A forceful vocal blast pushes enemies away; the complete three-word shout can launch them into the air.","sources":[{"label":"Bethesda · Creating Skyrim’s Dragon Language","url":"https://elderscrolls.bethesda.net/en-AU/news/1rL4bCScN6RYXaXQb4ownj/how-bethesda-game-studios-made-skyrims-dragon-language"},{"label":"Bethesda · Memorable Skyrim Moments","url":"https://elderscrolls.bethesda.net/zh-TW/news/7-memorable-moments-from-the-elder-scrolls-v-skyrim"}],"media":[{"alt":"An expanding wave of force sweeping across a rugged landscape","type":"image","id":"fus-ro-dah-illustration","url":"/visuals/spells/fus-ro-dah.png","credit":"AI-generated illustration · Spelling Spells","caption":"Original illustration inspired by the spell’s fictional effect"}],"sourceIds":["Source_3_Reference_2026-10-21_e9ffeb83-7d3c-4cb6-85c1-b3558a34e9e9","Source_4_Reference_2026-10-21_a707279a-2ba2-4a87-82b3-8aecf65954df"],"slug":"fus-ro-dah"}'::jsonb) on conflict (id) do update set universe_id = excluded.universe_id, name = excluded.name, payload = excluded.payload, status = excluded.status, revision = public.catalog_spells.revision + 1, updated_at = clock_timestamp() where public.catalog_spells.payload ->> 'seedPlaceholder' = 'true' and public.catalog_spells.number = excluded.number and public.catalog_spells.slug = excluded.slug returning id) insert into catalog_seed_accepted (id) select id from accepted;
with accepted as (insert into public.catalog_spells (id, number, slug, name, universe_id, status, payload) values ('Spell_3_Brisingr_2026-10-06_719dd0e3-506a-4e67-9b02-04d4af1b4933', 3, 'brisingr', 'Brisingr', 'inheritance-cycle', 'published', '{"id":"Spell_3_Brisingr_2026-10-06_719dd0e3-506a-4e67-9b02-04d4af1b4933","number":3,"name":"Brisingr","worldId":"inheritance-cycle","sourceTitle":"Inheritance Cycle","medium":"Books","kind":"Word of Power","language":"Ancient Language","pronunciation":"BRISS-ing-gur","pronunciationNote":"Paolini’s official website supplies this pronunciation for the sword bearing the same word, and provides an audio pronunciation guide.","syllables":["BRISS","ing","gur"],"definition":"The Ancient Language word for fire, used in the series’ magic.","usage":"A fire-related word of power. A word’s translation alone does not describe every possible magical effect.","etymology":"Paolini explains that he found brisingr, meaning fire, in an Old Norse word-origin reference and used it as inspiration for the Ancient Language.","etymologyStatus":"Confirmed","breakdown":[{"label":"Brisingr","meaning":"Fire — the complete Ancient Language word."}],"danger":4,"utility":4,"skill":"Intermediate","category":"Fire","accent":"fire","aliases":["Fire","Ancient Language"],"casters":[],"entryType":"incantation","evidenceStatus":"verified","pronunciationStatus":"verified","continuity":"Inheritance Cycle novels; Ancient Language word entry","effect":"Names fire in the Ancient Language and supplies a fire-related word for magic; the intended result depends on how it is used.","sources":[{"label":"Christopher Paolini · Language Origins FAQ","url":"https://www.paolini.net/faq/"},{"label":"Christopher Paolini · Brisingr Pronunciation","url":"https://www.paolini.net/2018/06/11/man-arms-brisingr/"},{"label":"Christopher Paolini · Official Audio Guide","url":"https://www.paolini.net/audio-pronunciation-guide/things/"}],"media":[{"alt":"Swirling flames glowing against a dar