with accepted as (insert into public.catalog_spells (id, number, slug, name, universe_id, status, payload) values ('Spell_5_Wingardium-Leviosa_2026-10-06_719dd0e5-506a-4e67-9b02-04d4af1b4935', 5, 'wingardium-leviosa', 'Wingardium Leviosa', 'harry-potter', 'published', '{"id":"Spell_5_Wingardium-Leviosa_2026-10-06_719dd0e5-506a-4e67-9b02-04d4af1b4935","number":5,"name":"Wingardium Leviosa","worldId":"harry-potter","sourceTitle":"Harry Potter","medium":"Books","kind":"Levitation Charm","language":"Latin-inspired incantation","pronunciation":"win-GAR-dee-um leh-vee-OH-suh","pronunciationNote":"An English reader aid. The official guide emphasizes the Levi-o-sa pronunciation; the full respelling here is not an official transcription.","syllables":["win","GAR","di","um","le","vi","O","sa"],"definition":"Makes an object levitate.","usage":"Associated with the swish-and-flick wand movement and careful pronunciation.","etymology":"The supplied official reference explains the charm’s use, but does not establish a complete linguistic derivation.","etymologyStatus":"Unconfirmed","breakdown":[{"label":"Wingardium","meaning":"First word of the incantation."},{"label":"Leviosa","meaning":"Second word; the official guide highlights its pronunciation."}],"danger":2,"utility":4,"skill":"Beginner","category":"Levitation","accent":"wand","aliases":["Levitation Charm","Swish and Flick"],"entryType":"spell","evidenceStatus":"verified","pronunciationStatus":"approximate","casters":["Ron Weasley","Hermione Granger"],"continuity":"Harry Potter novels; the cited lesson is from Philosopher’s Stone","effect":"Raises an object into the air. Ron uses the charm on a mountain troll’s club after learning it in Professor Flitwick’s class.","sources":[{"label":"Harry Potter · Official Spell Guide","url":"https://www.harrypotter.com/features/your-guide-to-the-best-spells-in-harry-potter"},{"label":"Harry Potter · Philosopher’s Stone Spell Guide","url":"https://www.harrypotter.com/features/guide-to-the-spells-creatures-and-potions-of-philosophers-stone"}],"media":[{"alt":"A feather suspended in the air by levitation magic","type":"image","id":"wingardium-leviosa-illustration","url":"/visuals/spells/wingardium-leviosa.png","credit":"AI-generated illustration · Spelling Spells","caption":"Original illustration inspired by the spell’s fictional effect"}],"sourceIds":["Source_9_Reference_2026-10-21_2c7f70b2-f1eb-4c39-8e54-b101012a49a8","Source_8_Reference_2026-10-21_7a1670a2-7b09-4165-8f42-2dadcd19051e"],"slug":"wingardium-leviosa"}'::jsonb) on conflict (id) do update set universe_id = excluded.universe_id, name = excluded.name, payload = excluded.payload, status = excluded.status, revision = public.catalog_spells.revision + 1, updated_at = clock_timestamp() where public.catalog_spells.payload ->> 'seedPlaceholder' = 'true' and public.catalog_spells.number = excluded.number and public.catalog_spells.slug = excluded.slug returning id) insert into catalog_seed_accepted (id) select id from accepted;
with accepted as (insert into public.catalog_spells (id, number, slug, name, universe_id, status, payload) values ('Spell_6_Expelliarmus_2026-10-06_719dd0e6-506a-4e67-9b02-04d4af1b4936', 6, 'expelliarmus', 'Expelliarmus', 'harry-potter', 'published', '{"id":"Spell_6_Expelliarmus_2026-10-06_719dd0e6-506a-4e67-9b02-04d4af1b4936","number":6,"name":"Expelliarmus","worldId":"harry-potter","sourceTitle":"Harry Potter","medium":"Books","kind":"Disarming Charm","language":"Latin-inspired incantation","pronunciation":"ex-PELL-ee-AR-muss","pronunciationNote":"An English reader aid rather than an official phonetic transcription. Performances may vary.","syllables":["ex","PELL","i","AR","mus"],"definition":"Forces an opponent to release what they are holding, often a wand.","usage":"A practical disarming charm associated with Harry’s duelling.","etymology":"The official guide describes a combination of Latin with the approximate sense of driving out a weapon.","etymologyStatus":"Confirmed","breakdown":[{"label":"Expelliarmus","meaning":"The official explanation gives the combined meaning “drive out a weapon”; no exact morpheme boundary is claimed here."}],"danger":3,"utility":4,"skill":"Intermediate","category":"Defense","accent":"wand","aliases":["Disarming Charm","Harry’s Signature Spell"],"entryType":"spell","evidenceStatus":"verified","pronunciationStatus":"approximate","casters":["Harry Potter","Severus Snape"],"continuity":"Harry Potter novels; Harry learns it during the Chamber of Secrets Duelling Club","effect":"Makes a target release a held object, commonly a wand, and gives a duellist a way to disarm an opponent.","sources":[{"label":"Harry Potter · Harry’s Signature Spell","url":"https://www.harrypotter.com/features/expelliarmus-exploring-harry-potters-signature-spell"}],"media":[{"alt":"A wand flying away amid a burst of disarming magic","type":"image","id":"expelliarmus-illustration","url":"/visuals/spells/expelliarmus.png","credit":"AI-generated illustration · Spe