excluded.payload, status = excluded.status, revision = public.catalog_spells.revision + 1, updated_at = clock_timestamp() where public.catalog_spells.payload ->> 'seedPlaceholder' = 'true' and public.catalog_spells.number = excluded.number and public.catalog_spells.slug = excluded.slug returning id) insert into catalog_seed_accepted (id) select id from accepted;
do $catalog_validation$
declare entry public.catalog_spells%rowtype;
begin
  for entry in select s.* from public.catalog_spells s join catalog_seed_accepted accepted on accepted.id = s.id loop
    perform app_private.validate_catalog_payload(entry.payload);
    if entry.status = 'published' and (
      entry.payload ->> 'evidenceStatus' is distinct from 'verified'
      or nullif(btrim(entry.payload ->> 'continuity'), '') is null
      or nullif(btrim(entry.payload ->> 'sourceTitle'), '') is null
      or nullif(btrim(entry.payload ->> 'kind'), '') is null
      or not exists (select 1 from public.catalog_universes where id = entry.universe_id)
      or not exists (select 1 from public.catalog_spell_sources where spell_id = entry.id)
      or exists (select 1 from jsonb_array_elements_text(entry.payload -> 'sourceIds') requested(id)
        left join public.catalog_spell_sources r on r.spell_id = entry.id and r.source_id = requested.id where r.source_id is null)
      or (select count(*) from public.catalog_spell_sources where spell_id = entry.id) <> jsonb_array_length(entry.payload -> 'sourceIds')
    ) then raise exception 'Verify The Imported Entry And Its Sources Before Publication: %', entry.name; end if;
  end loop;
end;
$catalog_validation$;
update app_private.counters set number = greatest(number, coalesce((select max(number) from public.catalog_spells), 0)) where name = 'catalog_spells';
update app_private.counters set number = greatest(number, coalesce((select max(number) from public.catalog_universes), 0)) where name = 'catalog_universes';
update app_private.counters set number = greatest(number, coalesce((select max(number) from public.catalog_sources), 0)) where name = 'catalog_sources';
commit;
